package com.nigson.experience.careers;

import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;
import java.time.*;import java.util.*;import java.util.regex.Pattern;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.JsonNode;

/** Experience-owned career operations. Provider anti-abuse verification is an optional fail-closed port. */
public final class CareerService {
 @FunctionalInterface public interface AntiSpamVerifier { boolean verify(String token,String idempotencyKey); }
 public record Opportunity(UUID id,String title,String slug,String kind,String description,JsonNode fieldsSchema,Instant closesAt,String state,long version){}
 public record Page<T>(List<T> items,int page,int size,long total){}
 public record Summary(UUID id,UUID opportunityId,String name,String state,Instant createdAt){}
 public record Application(UUID id,UUID opportunityId,String name,String email,JsonNode answers,UUID cvFileId,String state,long version){}
 public record SheetContext(UUID applicationId,String opportunityTitle,String name,String email,Instant submittedAt,String state,JsonNode approvedAnswers){}
 public record Created(UUID id,String state){} public record Changed(UUID id,String state,long version){}
 private final JdbcTemplate jdbc;private final PlatformStore store;private final AuditWriter audit;private final TransactionTemplate tx;private final CareerSecrets secrets;private final Clock clock;private final int retentionDays;private final String policyVersion,recipientGroup;private final Set<String> sheetFields;private final AntiSpamVerifier antiSpam;
 public CareerService(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,CareerSecrets secrets,PlatformTransactionManager manager,Clock clock,int retentionDays,String policyVersion,String recipientGroup,Set<String> sheetFields,AntiSpamVerifier antiSpam){this.jdbc=jdbc;this.store=store;this.audit=audit;this.tx=new TransactionTemplate(manager);this.secrets=secrets;this.clock=clock;this.retentionDays=retentionDays;this.policyVersion=policyVersion;this.recipientGroup=recipientGroup;this.sheetFields=Set.copyOf(sheetFields);this.antiSpam=antiSpam;}
 private static final Pattern EMAIL=Pattern.compile("(?i)^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)+$");
 private static PrivateWorkload.Route route(String api){return PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);}
  private void staff(PrivateWorkload.Proof p,String api,String permission){if(p==null||p.actor()==null||!route(api).equals(p.route())||!"nigson-commerce".equals(p.client())||!p.actor().roles().contains("SALES")||!p.actor().scopes().contains(permission))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private UUID correlation(UUID value){return value==null?WireCorrelation.current():value;}
 private boolean intakeConfigured(){return retentionDays>=1&&retentionDays<=3650&&policyVersion!=null&&!policyVersion.isBlank()&&policyVersion.length()<=80&&recipientGroup!=null&&!recipientGroup.isBlank()&&recipientGroup.length()<=1000&&recipientGroup.chars().noneMatch(c->c<32||c==127)&&antiSpam!=null&&secrets!=null;}
 public Page<Opportunity> publicOpportunities(String kind,int page,int size,String sort){bounds(page,size);if(kind!=null&&!CareerValues.KINDS.contains(kind)||!CareerValues.PUBLIC_SORTS.contains(sort))throw ApiValues.invalid();String order=switch(sort){case "createdAt,asc"->"created_at ASC";case "title,asc"->"title ASC";case "title,desc"->"title DESC";default->"created_at DESC";};String sql="SELECT id,title,slug,kind,description,fields_schema,closes_at,state,version FROM experience.career_opportunity WHERE state='PUBLISHED' AND deleted_at IS NULL AND (closes_at IS NULL OR closes_at>?)"+(kind==null?"":" AND kind=?")+" ORDER BY "+order+",id LIMIT ? OFFSET ?";var rows=kind==null?jdbc.query(sql,(r,n)->opportunity(r,n),Timestamp(clock.instant()),size,(long)page*size):jdbc.query(sql,(r,n)->opportunity(r,n),Timestamp(clock.instant()),kind,size,(long)page*size);Long total=kind==null?jdbc.queryForObject("SELECT count(*) FROM experience.career_opportunity WHERE state='PUBLISHED' AND deleted_at IS NULL AND (closes_at IS NULL OR closes_at>?)",Long.class,Timestamp(clock.instant())):jdbc.queryForObject("SELECT count(*) FROM experience.career_opportunity WHERE state='PUBLISHED' AND deleted_at IS NULL AND (closes_at IS NULL OR closes_at>?) AND kind=?",Long.class,Timestamp(clock.instant()),kind);return new Page<>(rows,page,size,total==null?0:total);}
 private Opportunity opportunity(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Opportunity(r.getObject("id",UUID.class),r.getString("title"),r.getString("slug"),r.getString("kind"),r.getString("description"),EventCodec.JSON.readTree(r.getString("fields_schema")),r.getTimestamp("closes_at")==null?null:r.getTimestamp("closes_at").toInstant(),r.getString("state"),r.getLong("version"));}
 public Opportunity create(PrivateWorkload.Proof proof,CareerValues.OpportunityInput input,String key,UUID correlation){staff(proof,"API-104","careers.write_WITH_SIGNED_ACTOR");CareerValues.validateOpportunity(input);if(input.closesAt()!=null&&!input.closesAt().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);UUID id=EventCodec.uuid7(clock.instant());Opportunity dto=new Opportunity(id,input.title(),input.slug(),input.kind(),input.description(),input.fieldsSchema(),input.closesAt(),input.state(),0);var response=store.executeLocal(proof.actor().party().toString(),"API-104",key,EventCodec.JSON.valueToTree(input),db->{db.update("INSERT INTO experience.career_opportunity(id,created_by,updated_by,title,slug,kind,description,fields_schema,state,closes_at) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?)",id,proof.actor().party().toString(),proof.actor().party().toString(),input.title(),input.slug(),input.kind(),input.description(),EventCodec.JSON.writeValueAsString(input.fieldsSchema()),input.state(),input.closesAt()==null?null:Timestamp(input.closesAt()));audit.append(proof.actor().party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MODERATION,AuditValues.Resource.CONTENT,id,correlation(correlation),AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state",input.state(),"kind",input.kind()),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(dto),id);});return EventCodec.JSON.treeToValue(response.body(),Opportunity.class);}
 public Created submit(UUID opportunityId,CareerValues.Submission input,String uploadToken,String key,UUID correlation){if(!intakeConfigured())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);key=ApiValues.idempotencyKey(key);if(input==null||input.antiSpamToken()==null||input.antiSpamToken().length()>4096||!antiSpam.verify(input.antiSpamToken(),key))throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);if(input.name()==null||CareerValues.text(input.name(),160)==null||!input.name().strip().equals(input.name())||input.email()==null||input.email().length()>254||!EMAIL.matcher(input.email()).matches()||!Objects.equals(policyVersion,input.privacyPolicyVersion())||(input.cvFileId()==null)!=(uploadToken==null))throw ApiValues.invalid();UUID id=EventCodec.uuid7(clock.instant());String email=input.email().strip().toLowerCase(Locale.ROOT);byte[] encrypted=secrets.encrypt(id,email);String hash=secrets.fingerprint(email);var request=EventCodec.JSON.valueToTree(input);var response=store.executeLocal("public:career","API-105:"+opportunityId,key,request,db->{var ops=db.queryForList("SELECT id,fields_schema FROM experience.career_opportunity WHERE id=? AND state='PUBLISHED' AND deleted_at IS NULL AND (closes_at IS NULL OR closes_at>?) FOR UPDATE",opportunityId,Timestamp(clock.instant()));if(ops.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);JsonNode schema=EventCodec.JSON.readTree(ops.getFirst().get("fields_schema").toString());CareerValues.validateAnswers(schema,input.answers());UUID cv=input.cvFileId();if(cv!=null){byte[] capabilityHash;try{if(uploadToken.isBlank()||uploadToken.length()>512)throw new IllegalArgumentException();capabilityHash=java.security.MessageDigest.getInstance("SHA-256").digest(uploadToken.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);}String supplied=java.util.HexFormat.of().formatHex(capabilityHash);var files=db.queryForList("SELECT f.id,f.upload_session_id,f.purpose,f.classification,f.scan_status,f.linked_resource_id,f.owner_party_id,f.byte_size,u.purpose AS session_purpose,u.maximum_bytes,u.owner_party_id AS session_owner,u.expires_at,u.claimed_application_id,u.token_hash FROM experience.file_asset f JOIN experience.upload_session u ON u.id=f.upload_session_id WHERE f.id=? FOR UPDATE OF f,u",cv);if(files.size()!=1)throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);var f=files.getFirst();Object linked=f.get("linked_resource_id");String expected=((String)f.get("token_hash")).trim();if(!java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.US_ASCII),supplied.getBytes(java.nio.charset.StandardCharsets.US_ASCII))||!"CAREER_CV".equals(f.get("purpose"))||!"CAREER_CV".equals(f.get("session_purpose"))||f.get("owner_party_id")!=null||f.get("session_owner")!=null||((Number)f.get("byte_size")).longValue()>((Number)f.get("maximum_bytes")).longValue()||!"PRIVATE".equals(f.get("classification"))||!"CLEAN".equals(f.get("scan_status"))||linked!=null||f.get("claimed_application_id")!=null||!((java.sql.Timestamp)f.get("expires_at")).toInstant().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);}
  Instant now=clock.instant();db.update("INSERT INTO experience.career_application(id,created_by,updated_by,opportunity_id,name,email_ciphertext,email_hash,answers,form_revision,cv_file_id,state,retention_until) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?,?,?)",id,"public:career","public:career",opportunityId,input.name(),encrypted,hash,EventCodec.JSON.writeValueAsString(input.answers()),schema.path("schemaVersion").asInt(),cv,"SUBMITTED",Timestamp(now.plus(retentionDays,java.time.temporal.ChronoUnit.DAYS)));if(cv!=null){if(db.update("UPDATE experience.upload_session SET claimed_application_id=?,version=version+1,updated_at=?,updated_by='career-intake' WHERE id=(SELECT upload_session_id FROM experience.file_asset WHERE id=?) AND claimed_application_id IS NULL",id,Timestamp(now),cv)!=1)throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);if(db.update("UPDATE experience.file_asset SET linked_resource_type='CAREER_APPLICATION',linked_resource_id=?,version=version+1,updated_at=?,updated_by='career-intake' WHERE id=? AND linked_resource_id IS NULL",id,Timestamp(now),cv)!=1)throw new Problem.Failure(ProblemCode.CAREERS_RULE_VIOLATION);}
  var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(now));event.put("event_type","career.application.created.v1");event.put("schema_version",1);event.put("producer","experience");event.put("occurred_at",now.toString());event.put("aggregate_id",id);event.put("aggregate_version",0);event.put("organization_id",null);event.put("correlation_id",correlation(correlation));event.put("traceparent",null);event.put("payload",Map.of("application_id",id,"opportunity_id",opportunityId,"recipient_group",recipientGroup));store.append(EventCodec.JSON.writeValueAsString(event),"public:career");audit.append("public:career",AuditValues.ActorKind.SYSTEM,AuditValues.Action.APPLICANT_EXPORT,AuditValues.Resource.CAREER_APPLICATION,id,correlation(correlation),AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state","SUBMITTED","opportunityId",opportunityId),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new Created(id,"SUBMITTED")),id);});return EventCodec.JSON.treeToValue(response.body(),Created.class);}
 public Page<Summary> list(PrivateWorkload.Proof proof,UUID opportunityId,String state,int page,int size,String sort){staff(proof,"API-106","careers.read_WITH_SIGNED_ACTOR");bounds(page,size);if(state!=null&&!CareerValues.STATES.contains(state)||!CareerValues.APPLICATION_SORTS.contains(sort))throw ApiValues.invalid();String order=switch(sort){case "createdAt,asc"->"created_at ASC";case "name,asc"->"name ASC";case "name,desc"->"name DESC";default->"created_at DESC";};String filter=" WHERE (?::uuid IS NULL OR opportunity_id=?) AND (?::varchar IS NULL OR state=?)";var rows=jdbc.query("SELECT id,opportunity_id,name,state,created_at FROM experience.career_application"+filter+" ORDER BY "+order+",id LIMIT ? OFFSET ?",(r,n)->new Summary(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getTimestamp(5).toInstant()),opportunityId,opportunityId,state,state,size,(long)page*size);Long total=jdbc.queryForObject("SELECT count(*) FROM experience.career_application"+filter,Long.class,opportunityId,opportunityId,state,state);return new Page<>(rows,page,size,total==null?0:total);}
 public Application detail(PrivateWorkload.Proof proof,UUID id,UUID correlation){staff(proof,"API-156","careers.read_WITH_SIGNED_ACTOR");if(secrets==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);return tx.execute(status->{var rows=jdbc.queryForList("SELECT id,opportunity_id,name,email_ciphertext,answers,cv_file_id,state,version FROM experience.career_application WHERE id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var r=rows.getFirst();auditAccess(proof,id,correlation,"READ");return new Application((UUID)r.get("id"),(UUID)r.get("opportunity_id"),(String)r.get("name"),secrets.decrypt(id,(byte[])r.get("email_ciphertext")),EventCodec.JSON.readTree(r.get("answers").toString()),(UUID)r.get("cv_file_id"),(String)r.get("state"),((Number)r.get("version")).longValue());});}
 public Changed transition(PrivateWorkload.Proof proof,UUID id,CareerValues.Transition input,long expected,String key,UUID correlation){staff(proof,"API-107","careers.manage_WITH_SIGNED_ACTOR");if(input==null||!Set.of("REVIEWED","SHORTLISTED","REJECTED","CLOSED").contains(input.state())||CareerValues.text(input.reason(),500)==null||expected<0)throw ApiValues.invalid();var request=EventCodec.JSON.valueToTree(Map.of("id",id,"state",input.state(),"reason",input.reason(),"version",expected));var result=store.executeLocal(proof.actor().party().toString(),"API-107:"+id,key,request,db->{var rows=db.queryForList("SELECT state,version FROM experience.career_application WHERE id=? FOR UPDATE",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var old=rows.getFirst();String before=(String)old.get("state");long version=((Number)old.get("version")).longValue();if(version!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);Set<String> allowed=switch(before){case "SUBMITTED"->Set.of("REVIEWED","REJECTED","CLOSED");case "REVIEWED"->Set.of("SHORTLISTED","REJECTED","CLOSED");case "SHORTLISTED"->Set.of("REJECTED","CLOSED");case "REJECTED"->Set.of("CLOSED");default->Set.of();};if(!allowed.contains(input.state()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);int n=db.update("UPDATE experience.career_application SET state=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",input.state(),Timestamp(clock.instant()),proof.actor().party().toString(),id,expected);if(n!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);audit.append(proof.actor().party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MODERATION,AuditValues.Resource.CAREER_APPLICATION,id,correlation(correlation),AuditValues.Reason.OPERATOR_REQUEST,Map.of("state",before,"version",version),Map.of("state",input.state(),"reason",input.reason()),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Changed(id,input.state(),version+1)),id);});return EventCodec.JSON.treeToValue(result.body(),Changed.class);}
 public SheetContext sheet(PrivateWorkload.Proof proof,UUID id,UUID correlation){if(proof==null||proof.actor()!=null||!route("API-128").equals(proof.route())||!"nigson-integration".equals(proof.client())||!"sheets.read".equals(proof.route().scope()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(secrets==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);return tx.execute(status->{var rows=jdbc.queryForList("SELECT a.id,a.name,a.email_ciphertext,a.answers,a.state,a.created_at,o.title FROM experience.career_application a JOIN experience.career_opportunity o ON o.id=a.opportunity_id WHERE a.id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var r=rows.getFirst();JsonNode all=EventCodec.JSON.readTree(r.get("answers").toString());var selected=EventCodec.JSON.createObjectNode();for(String field:sheetFields)if(all.has(field))selected.set(field,all.get(field));auditAccess(proof,id,correlation,"SHEET_CONTEXT");return new SheetContext(id,(String)r.get("title"),(String)r.get("name"),secrets.decrypt(id,(byte[])r.get("email_ciphertext")),((java.sql.Timestamp)r.get("created_at")).toInstant(),(String)r.get("state"),selected);});}
 private void auditAccess(PrivateWorkload.Proof p,UUID id,UUID c,String action){audit.append(p.actor()==null?"service:"+p.client():p.actor().party().toString(),p.actor()==null?AuditValues.ActorKind.SERVICE:AuditValues.ActorKind.USER,AuditValues.Action.APPLICANT_EXPORT,AuditValues.Resource.CAREER_APPLICATION,id,correlation(c),AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("access",action),null);}
 private static void bounds(int page,int size){if(page<0||page>100000||size<1||size>100)throw ApiValues.invalid();}
 private static java.sql.Timestamp Timestamp(Instant i){return java.sql.Timestamp.from(i);}
 private static final class WireCorrelation {static UUID current(){var w=com.nigson.shared.observability.WireContext.current();return w==null?com.nigson.shared.observability.WireContext.correlation(null):w.correlationId;}}
}
